    // FileStructureInternalGlobalData
    internal static PrcFileStructureInternalGlobalData ReadFileStructureInternalGlobalData(ref PrcBitReader r, PrcContext ctx)
    {
        ctx.Enter("FileStructureInternalGlobalData", r.BitPosition);
        r.ReadDouble();
        r.ReadDouble();
        ReadMarkupSerializationHelper(ref r, ctx);
        uint color_count = r.ReadUnsignedInteger();
        PrcRgbColor[] colors = [];
        int colors__count = ctx.Count(ref r, (long)color_count, 6);
        ctx.Charge(colors__count * 24L);
        colors = new PrcRgbColor[Math.Min(colors__count, 256)];
        for (int i = 0; i < colors__count; i++)
        {
            if (i == colors.Length)
            {
                Array.Resize(ref colors, (int)Math.Min(colors.Length * 2L, colors__count));
            }

            colors[i] = ReadRgbColor(ref r, ctx);
        }
        uint picture_count = r.ReadUnsignedInteger();
        PrcGraphPicture[] pictures = [];
        int pictures__count = ctx.Count(ref r, (long)picture_count, 7);
        ctx.Charge(pictures__count * 64L);
        pictures = new PrcGraphPicture[Math.Min(pictures__count, 256)];
        for (int i = 0; i < pictures__count; i++)
        {
            if (i == pictures.Length)
            {
                Array.Resize(ref pictures, (int)Math.Min(pictures.Length * 2L, pictures__count));
            }

            pictures[i] = ReadGraphPicture(ref r, ctx);
        }
        uint texture_count = r.ReadUnsignedInteger();
        PrcGraphTextureDefinition[] textures = [];
        int textures__count = ctx.Count(ref r, (long)texture_count, 32);
        ctx.Charge(textures__count * 104L);
        textures = new PrcGraphTextureDefinition[Math.Min(textures__count, 256)];
        for (int i = 0; i < textures__count; i++)
        {
            if (i == textures.Length)
            {
                Array.Resize(ref textures, (int)Math.Min(textures.Length * 2L, textures__count));
            }

            textures[i] = ReadGraphTextureDefinition(ref r, ctx);
        }
        uint material_count = r.ReadUnsignedInteger();
        PrcMaterial[] materials = [];
        int materials__count = ctx.Count(ref r, (long)material_count, 1);
        ctx.Charge(materials__count * 40L);
        materials = new PrcMaterial[Math.Min(materials__count, 256)];
        for (int i = 0; i < materials__count; i++)
        {
            if (i == materials.Length)
            {
                Array.Resize(ref materials, (int)Math.Min(materials.Length * 2L, materials__count));
            }

            materials[i] = ReadMaterial(ref r, ctx);
        }
        uint line_pattern_count = r.ReadUnsignedInteger();
        for (int i = 0, n = ctx.Count(ref r, (long)line_pattern_count, 10); i < n; i++)
        {
            ReadGraphLinePattern(ref r, ctx);
        }
        uint style_count = r.ReadUnsignedInteger();
        PrcGraphStyle[] styles = [];
        int styles__count = ctx.Count(ref r, (long)style_count, 16);
        ctx.Charge(styles__count * 64L);
        styles = new PrcGraphStyle[Math.Min(styles__count, 256)];
        for (int i = 0; i < styles__count; i++)
        {
            if (i == styles.Length)
            {
                Array.Resize(ref styles, (int)Math.Min(styles.Length * 2L, styles__count));
            }

            styles[i] = ReadGraphStyle(ref r, ctx);
        }
        uint fill_count = r.ReadUnsignedInteger();
        for (int i = 0, n = ctx.Count(ref r, (long)fill_count, 1); i < n; i++)
        {
            ReadGraphFillPattern(ref r, ctx);
        }
        uint ref_coord_count = r.ReadUnsignedInteger();
        PrcRiCoordinateSystem[] ref_coords = [];
        int ref_coords__count = ctx.Count(ref r, (long)ref_coord_count, 11);
        ctx.Charge(ref_coords__count * 40L);
        ref_coords = new PrcRiCoordinateSystem[Math.Min(ref_coords__count, 256)];
        for (int i = 0; i < ref_coords__count; i++)
        {
            if (i == ref_coords.Length)
            {
                Array.Resize(ref ref_coords, (int)Math.Min(ref_coords.Length * 2L, ref_coords__count));
            }

            ref_coords[i] = ReadRiCoordinateSystem(ref r, ctx);
        }
        ctx.Leave();
        return new PrcFileStructureInternalGlobalData
        {
            Colors = colors,
            Pictures = pictures,
            Textures = textures,
            Materials = materials,
            Styles = styles,
            RefCoords = ref_coords,
        };
    }

