    // PRC_TYPE_ASM_ModelFile
    internal static PrcAsmModelFile ReadAsmModelFile(ref PrcBitReader r, PrcContext ctx)
    {
        ctx.Enter("PRC_TYPE_ASM_ModelFile", r.BitPosition);
        uint id = r.ReadUnsignedInteger();
        ctx.Expect(id, PrcType.PRC_TYPE_ASM_ModelFile, "PRC_TYPE_ASM_ModelFile");
        ReadContentPRCBase(ref r, ctx);
        bool units_from_cad_file = r.ReadBoolean();
        // units_in_mm: https://github.com/pdf-association/pdf-issues/issues/740
        double units_in_mm = r.ReadDouble();
        uint number_of_root_product_occurrences = r.ReadUnsignedInteger();
        PrcProductOccurrenceReference[] product_occurrences = [];
        int product_occurrences__count = ctx.Count(ref r, (long)number_of_root_product_occurrences, 6);
        ctx.Charge(product_occurrences__count * 24L);
        product_occurrences = new PrcProductOccurrenceReference[Math.Min(product_occurrences__count, 256)];
        for (int i = 0; i < product_occurrences__count; i++)
        {
            if (i == product_occurrences.Length)
            {
                Array.Resize(ref product_occurrences, (int)Math.Min(product_occurrences.Length * 2L, product_occurrences__count));
            }

            product_occurrences[i] = ReadProductOccurrenceReference(ref r, ctx);
        }
        // file_structure_index_in_model_file: https://github.com/pdf-association/pdf-issues/issues/724
        PrcArrays.SkipUnsignedIntegers(ref r, (long)ctx.FileStructureCount);
        ctx.Schema.Evaluate(ref r, PrcType.PRC_TYPE_ASM_ModelFile);
        ctx.Mark("UserData", r.BitPosition);
        r.SkipUserData();
        ctx.Leave();
        return new PrcAsmModelFile
        {
            UnitsFromCadFile = units_from_cad_file,
            UnitsInMm = units_in_mm,
            ProductOccurrences = product_occurrences,
        };
    }

