        PrcMkpMarkup[] markups = [];
        int markups__count = ctx.Count(ref r, (long)number_of_markups, 13);
        ctx.Charge(markups__count * 48L);
        markups = new PrcMkpMarkup[Math.Min(markups__count, 256)];
