    internal static PrcAsmProductOccurrence ReadAsmProductOccurrence(ref PrcBitReader r, PrcContext ctx)
    {
        ctx.Enter("PRC_TYPE_ASM_ProductOccurrence", r.BitPosition);
        uint id = r.ReadUnsignedInteger();
        ctx.Expect(id, PrcType.PRC_TYPE_ASM_ProductOccurrence, "PRC_TYPE_ASM_ProductOccurrence");
        PrcRootPRCBaseWithGraphics @base = ReadRootPRCBaseWithGraphics(ref r, ctx);
        PrcReferencesOfProductOccurrence references_product_occurrence = ReadReferencesOfProductOccurrence(ref r, ctx);
        sbyte product_behavior = r.ReadCharacter();
        PrcProductInformation product_information = ReadProductInformation(ref r, ctx);
        bool has_transformation = r.ReadBoolean();
        uint location__type = 0;
        object? location = null;
        if (has_transformation)
        {
            location__type = PrcContext.PeekUnsignedInteger(ref r);
            switch (location__type)
            {
                case PrcType.PRC_TYPE_MISC_CartesianTransformation:
                    location = ReadMiscCartesianTransformation(ref r, ctx);
                    break;
                case PrcType.PRC_TYPE_MISC_GeneralTransformation:
                    location = ReadMiscGeneralTransformation(ref r, ctx);
                    break;
                default:
                    ctx.UnknownType(ref r, "PRC_TYPE_ASM_ProductOccurrence.location", location__type);
                    break;
            }
        }
        uint entity_ref_count = r.ReadUnsignedInteger();
        PrcMiscEntityReference[] entity_reference = [];
        int entity_reference__count = ctx.Count(ref r, (long)entity_ref_count, 10);
        ctx.Charge(entity_reference__count * 40L);
        entity_reference = new PrcMiscEntityReference[Math.Min(entity_reference__count, 256)];
        for (int i = 0; i < entity_reference__count; i++)
        {
            if (i == entity_reference.Length)
            {
                Array.Resize(ref entity_reference, (int)Math.Min(entity_reference.Length * 2L, entity_reference__count));
            }

            entity_reference[i] = ReadMiscEntityReference(ref r, ctx);
        }
        PrcMarkupData markups = ReadMarkupData(ref r, ctx);
        uint number_of_views = r.ReadUnsignedInteger();
        for (int i = 0, n = ctx.Count(ref r, (long)number_of_views, 37); i < n; i++)
        {
            ReadMkpView(ref r, ctx);
        }
        bool has_filter = r.ReadBoolean();
        if (has_filter)
        {
            ReadAsmFilter(ref r, ctx);
        }
        uint number_of_display_filters = r.ReadUnsignedInteger();
        for (int i = 0, n = ctx.Count(ref r, (long)number_of_display_filters, 12); i < n; i++)
        {
            ReadAsmFilter(ref r, ctx);
        }
        uint number_of_scene_parameters = r.ReadUnsignedInteger();
        for (int i = 0, n = ctx.Count(ref r, (long)number_of_scene_parameters, 14); i < n; i++)
        {
            ReadGraphSceneDisplayParameters(ref r, ctx);
        }
        ctx.Schema.Evaluate(ref r, PrcType.PRC_TYPE_ASM_ProductOccurrence);
        ctx.Mark("UserData", r.BitPosition);
        r.SkipUserData();
        ctx.Leave();
        return new PrcAsmProductOccurrence
        {
            Base = @base,
            ReferencesProductOccurrence = references_product_occurrence,
            ProductBehavior = product_behavior,
            ProductInformation = product_information,
            Location = location,
            LocationType = location__type,
            EntityReference = entity_reference,
            Markups = markups,
        };
    }

