        uint size_of_triangulateddata = r.ReadUnsignedInteger();
        uint[] triangulateddata = PrcArrays.ReadUnsignedIntegers(ref r, ctx, (long)size_of_triangulateddata);
        ctx.SetFace(used_entities_flag, triangulateddata);
        uint number_of_textured_coordinate_indices = r.ReadUnsignedInteger();
        bool has_vertex_colors = r.ReadBoolean();
        PrcVertexColors? vertex_color_data = null;
        if (has_vertex_colors)
        {
