    // PRC_TYPE_TESS_3D
    internal static PrcTess3D ReadTess3D(ref PrcBitReader r, PrcContext ctx)
    {
        ctx.Enter("PRC_TYPE_TESS_3D", r.BitPosition);
        uint id = r.ReadUnsignedInteger();
        ctx.Expect(id, PrcType.PRC_TYPE_TESS_3D, "PRC_TYPE_TESS_3D");
        PrcContentBaseTessData tessellation_coordinates = ReadContentBaseTessData(ref r, ctx);
        bool has_faces = r.ReadBoolean();
        // has_loops: https://github.com/pdf-association/pdf-issues/issues/705
        bool has_loops = false;
        if (ctx.AuthoringVersion >= 7039)
        {
            has_loops = r.ReadBoolean();
        }
        // must_calculate_normals: https://github.com/pdf-association/pdf-issues/issues/705
        bool must_calculate_normals = false;
        if (ctx.AuthoringVersion >= 7047)
        {
            must_calculate_normals = r.ReadBoolean();
        }
        // normal_recalculation_flags: https://github.com/pdf-association/pdf-issues/issues/705
        if (must_calculate_normals && ctx.AuthoringVersion >= 7047)
        {
            r.ReadCharacter();
        }
        // crease_angle: https://github.com/pdf-association/pdf-issues/issues/705
        double crease_angle = 0;
        if (must_calculate_normals && ctx.AuthoringVersion >= 7047)
        {
            crease_angle = r.ReadDouble();
        }
        uint number_of_normal_coordinates = r.ReadUnsignedInteger();
        double[] normal_coordinates = PrcArrays.ReadDoubles(ref r, ctx, (long)number_of_normal_coordinates);
        uint number_of_wire_indices = r.ReadUnsignedInteger();
        uint[] wire_indices = PrcArrays.ReadUnsignedIntegers(ref r, ctx, (long)number_of_wire_indices);
        uint number_of_triangulated_indicies = r.ReadUnsignedInteger();
        uint[] triangulated_index_array = PrcArrays.ReadUnsignedIntegers(ref r, ctx, (long)number_of_triangulated_indicies);
        uint number_of_face_tessellation = r.ReadUnsignedInteger();
        PrcTessFace[] face_tessellation_data = [];
        int face_tessellation_data__count = ctx.Count(ref r, (long)number_of_face_tessellation, 9);
        ctx.Charge(face_tessellation_data__count * 104L);
        face_tessellation_data = new PrcTessFace[Math.Min(face_tessellation_data__count, 256)];
        for (int i = 0; i < face_tessellation_data__count; i++)
        {
            if (i == face_tessellation_data.Length)
            {
                Array.Resize(ref face_tessellation_data, (int)Math.Min(face_tessellation_data.Length * 2L, face_tessellation_data__count));
            }

            face_tessellation_data[i] = ReadTessFace(ref r, ctx);
        }
        uint number_of_texture_coordinates = r.ReadUnsignedInteger();
        double[] texture_coordinates = PrcArrays.ReadDoubles(ref r, ctx, (long)number_of_texture_coordinates);
        ctx.Schema.Evaluate(ref r, PrcType.PRC_TYPE_TESS_3D);
        ctx.Leave();
        return new PrcTess3D
        {
            TessellationCoordinates = tessellation_coordinates,
            HasFaces = has_faces,
            HasLoops = has_loops,
            MustCalculateNormals = must_calculate_normals,
            CreaseAngle = crease_angle,
            NormalCoordinates = normal_coordinates,
            WireIndices = wire_indices,
            TriangulatedIndexArray = triangulated_index_array,
            FaceTessellationData = face_tessellation_data,
            TextureCoordinates = texture_coordinates,
        };
    }

