    // PRC_TYPE_TESS
    internal static PrcTess ReadTess(ref PrcBitReader r, PrcContext ctx)
    {
        ctx.Enter("PRC_TYPE_TESS", r.BitPosition);
        uint id__type = 0;
        object? id = null;
        id__type = PrcContext.PeekUnsignedInteger(ref r);
        switch (id__type)
        {
            case PrcType.PRC_TYPE_TESS_3D:
                id = ReadTess3D(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_TESS_3D_Wire:
                ReadTess3DWire(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_TESS_Markup:
                id = ReadTessMarkup(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_TESS_3D_Compressed:
                id = ReadTess3DCompressed(ref r, ctx);
                break;
            default:
                ctx.UnknownType(ref r, "PRC_TYPE_TESS.id", id__type);
                break;
        }
        ctx.Schema.Evaluate(ref r, PrcType.PRC_TYPE_TESS);
        ctx.Leave();
        return new PrcTess
        {
            Id = id,
            IdType = id__type,
        };
