        uint id = r.ReadUnsignedInteger();
        ctx.Expect(id, PrcType.PRC_TYPE_CRV_Blend02Boundary, "PRC_TYPE_CRV_Blend02Boundary");
        ReadContentCurve(ref r, ctx);
        if (!ctx.CurveIs3D)
        {
            ReadTransformation2DWithBit(ref r, ctx);
        }
        if (ctx.CurveIs3D)
        {
            ReadTransformation3DWithBit(ref r, ctx);
        }
        ReadParameterization(ref r, ctx);
        ReadPtrSurface(ref r, ctx);
        r.ReadInteger();
        uint number_of_crossing_points = r.ReadUnsignedInteger();
        for (int i = 0, n = ctx.Count(ref r, (long)number_of_crossing_points, 6); i < n; i++)
        {
            ReadVector3D(ref r, ctx);
        }
        r.ReadDouble();
        r.ReadDouble();
        ReadPtrSurface(ref r, ctx);
        r.ReadBoolean();
        r.ReadBoolean();
        r.ReadBoolean();
        r.ReadDouble();
        r.ReadDouble();
        ReadVector3D(ref r, ctx);
        r.ReadUnsignedInteger();
        ReadVector3D(ref r, ctx);
        r.ReadUnsignedInteger();
        ctx.Schema.Evaluate(ref r, PrcType.PRC_TYPE_CRV_Blend02Boundary);
        ctx.Leave();
