    // PRC_TYPE_CRV_NURBS
    internal static PrcCrvNurbs ReadCrvNurbs(ref PrcBitReader r, PrcContext ctx)
    {
        ctx.Enter("PRC_TYPE_CRV_NURBS", r.BitPosition);
        uint id = r.ReadUnsignedInteger();
        ctx.Expect(id, PrcType.PRC_TYPE_CRV_NURBS, "PRC_TYPE_CRV_NURBS");
        PrcContentCurve curve_data = ReadContentCurve(ref r, ctx);
        bool is_rational = r.ReadBoolean();
        ctx.NurbsCurveIsRational = is_rational;
        uint degree = r.ReadUnsignedInteger();
        uint highest_index_of_control_points = r.ReadUnsignedInteger();
        uint highest_index_of_knots = r.ReadUnsignedInteger();
        PrcControlPointsNurbsCrv[] p = [];
        int p__count = ctx.Count(ref r, (long)highest_index_of_control_points + 1, 4);
        ctx.Charge(p__count * 32L);
        p = new PrcControlPointsNurbsCrv[Math.Min(p__count, 256)];
        for (int i = 0; i < p__count; i++)
        {
            if (i == p.Length)
            {
                Array.Resize(ref p, (int)Math.Min(p.Length * 2L, p__count));
            }

            p[i] = ReadControlPointsNurbsCrv(ref r, ctx);
        }
        double[] u = PrcArrays.ReadDoubles(ref r, ctx, (long)highest_index_of_knots + 1);
        r.ReadUnsignedInteger();
        r.ReadUnsignedInteger();
        ctx.Schema.Evaluate(ref r, PrcType.PRC_TYPE_CRV_NURBS);
        ctx.Leave();
        return new PrcCrvNurbs
        {
            CurveData = curve_data,
            IsRational = is_rational,
            Degree = degree,
            P = p,
            U = u,
        };
    }

