        PrcContentCurve curve_data = ReadContentCurve(ref r, ctx);
        if (!ctx.CurveIs3D)
        {
            ReadTransformation2DWithBit(ref r, ctx);
        }
        PrcTransformation3DWithBit? transform3d = null;
