        uint number_of_crossings = r.ReadUnsignedInteger();
        PrcCrossingPointsCrvIntersection[] crossings = [];
        int crossings__count = ctx.Count(ref r, (long)number_of_crossings, 32);
        ctx.Charge(crossings__count * 16L);
        crossings = new PrcCrossingPointsCrvIntersection[Math.Min(crossings__count, 256)];
        for (int i = 0; i < crossings__count; i++)
        {
