    // PRC_TYPE_CRV
    internal static PrcCrv ReadCrv(ref PrcBitReader r, PrcContext ctx)
    {
        ctx.Enter("PRC_TYPE_CRV", r.BitPosition);
        uint id__type = 0;
        object? id = null;
        id__type = PrcContext.PeekUnsignedInteger(ref r);
        switch (id__type)
        {
            case PrcType.PRC_TYPE_ROOT:
                ReadRoot(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_CRV_Blend02Boundary:
                ReadCrvBlend02Boundary(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_CRV_NURBS:
                id = ReadCrvNurbs(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_CRV_Circle:
                id = ReadCrvCircle(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_CRV_Composite:
                id = ReadCrvComposite(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_CRV_OnSurf:
                ReadCrvOnSurf(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_CRV_Ellipse:
                id = ReadCrvEllipse(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_CRV_Equation:
                ReadCrvEquation(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_CRV_Helix:
                ReadCrvHelix(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_CRV_Hyperbola:
                ReadCrvHyperbola(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_CRV_Intersection:
                id = ReadCrvIntersection(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_CRV_Line:
                id = ReadCrvLine(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_CRV_Offset:
                ReadCrvOffset(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_CRV_Parabola:
                ReadCrvParabola(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_CRV_PolyLine:
                id = ReadCrvPolyLine(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_CRV_Transform:
                ReadCrvTransform(ref r, ctx);
                break;
            default:
                ctx.UnknownType(ref r, "PRC_TYPE_CRV.id", id__type);
                break;
        }
        ctx.Schema.Evaluate(ref r, PrcType.PRC_TYPE_CRV);
        ctx.Leave();
        return new PrcCrv
        {
            Id = id,
            IdType = id__type,
        };
    }

