    // PRC_TYPE_SURF_Blend03
    internal static void ReadSurfBlend03(ref PrcBitReader r, PrcContext ctx)
    {
        ctx.Enter("PRC_TYPE_SURF_Blend03", r.BitPosition);
        uint id = r.ReadUnsignedInteger();
        ctx.Expect(id, PrcType.PRC_TYPE_SURF_Blend03, "PRC_TYPE_SURF_Blend03");
        ReadContentSurface(ref r, ctx);
        ReadTransformation3DWithBit(ref r, ctx);
        ReadUVParameterization(ref r, ctx);
        // number_of_elements: https://github.com/pdf-association/pdf-issues/issues/654
        uint number_of_elements = r.ReadUnsignedInteger();
        PrcArrays.SkipDoubles(ref r, (long)number_of_elements);
        PrcArrays.SkipIntegers(ref r, (long)number_of_elements);
        for (int i = 0, n = ctx.Count(ref r, (long)number_of_elements * 3, 6); i < n; i++)
        {
            ReadVector3D(ref r, ctx);
        }
        PrcArrays.SkipDoubles(ref r, (long)number_of_elements);
        for (int i = 0, n = ctx.Count(ref r, (long)number_of_elements * 3, 6); i < n; i++)
        {
            ReadVector3D(ref r, ctx);
        }
        PrcArrays.SkipDoubles(ref r, (long)number_of_elements);
        for (int i = 0, n = ctx.Count(ref r, (long)number_of_elements * 3, 6); i < n; i++)
        {
            ReadVector3D(ref r, ctx);
        }
        PrcArrays.SkipDoubles(ref r, (long)number_of_elements);
        r.ReadDouble();
        r.ReadDouble();
        r.ReadDouble();
        for (int i = 0; i < 6; i++)
        {
            r.ReadInteger();
        }
        for (int i = 0; i < 3; i++)
        {
            r.ReadCharacter();
        }
        // number_of_supplimental_doubles: https://github.com/pdf-association/pdf-issues/issues/654
        uint number_of_supplimental_doubles = r.ReadUnsignedInteger();
        PrcArrays.SkipDoubles(ref r, (long)number_of_supplimental_doubles);
        ctx.Schema.Evaluate(ref r, PrcType.PRC_TYPE_SURF_Blend03);
        ctx.Leave();
    }

