    // PRC_TYPE_SURF_NURBS
    internal static PrcSurfNurbs ReadSurfNurbs(ref PrcBitReader r, PrcContext ctx)
    {
        ctx.Enter("PRC_TYPE_SURF_NURBS", r.BitPosition);
        uint id = r.ReadUnsignedInteger();
        ctx.Expect(id, PrcType.PRC_TYPE_SURF_NURBS, "PRC_TYPE_SURF_NURBS");
        ReadContentSurface(ref r, ctx);
        bool is_rational = r.ReadBoolean();
        uint du = r.ReadUnsignedInteger();
        uint dv = r.ReadUnsignedInteger();
        uint highest_index_of_control_points_in_u = r.ReadUnsignedInteger();
        uint highest_index_of_control_points_in_v = r.ReadUnsignedInteger();
        uint highest_index_of_knots_in_u = r.ReadUnsignedInteger();
        uint highest_index_of_knots_in_v = r.ReadUnsignedInteger();
        PrcControlPointsNurbsSurf3[] p3 = [];
        if (!is_rational)
        {
            int p3__count = ctx.Count(ref r, ((long)highest_index_of_control_points_in_u + 1) * ((long)highest_index_of_control_points_in_v + 1), 6);
            ctx.Charge(p3__count * 24L);
            p3 = new PrcControlPointsNurbsSurf3[Math.Min(p3__count, 256)];
            for (int i = 0; i < p3__count; i++)
            {
                if (i == p3.Length)
                {
                    Array.Resize(ref p3, (int)Math.Min(p3.Length * 2L, p3__count));
                }

                p3[i] = ReadControlPointsNurbsSurf3(ref r, ctx);
            }
        }
        PrcControlPointsNurbsSurf4[] p4 = [];
        if (is_rational)
        {
            int p4__count = ctx.Count(ref r, ((long)highest_index_of_control_points_in_u + 1) * ((long)highest_index_of_control_points_in_v + 1), 8);
            ctx.Charge(p4__count * 32L);
            p4 = new PrcControlPointsNurbsSurf4[Math.Min(p4__count, 256)];
            for (int i = 0; i < p4__count; i++)
            {
                if (i == p4.Length)
                {
                    Array.Resize(ref p4, (int)Math.Min(p4.Length * 2L, p4__count));
                }

                p4[i] = ReadControlPointsNurbsSurf4(ref r, ctx);
            }
        }
        double[] ku = PrcArrays.ReadDoubles(ref r, ctx, (long)highest_index_of_knots_in_u + 1);
        double[] kv = PrcArrays.ReadDoubles(ref r, ctx, (long)highest_index_of_knots_in_v + 1);
        r.ReadUnsignedInteger();
        r.ReadUnsignedInteger();
        ctx.Schema.Evaluate(ref r, PrcType.PRC_TYPE_SURF_NURBS);
        ctx.Leave();
        return new PrcSurfNurbs
        {
            IsRational = is_rational,
            Du = du,
            Dv = dv,
            HighestIndexOfControlPointsInU = highest_index_of_control_points_in_u,
            HighestIndexOfControlPointsInV = highest_index_of_control_points_in_v,
            P3 = p3,
            P4 = p4,
            Ku = ku,
            Kv = kv,
        };
    }

