        switch (id__type)
        {
            case PrcType.PRC_TYPE_TOPO_SingleWireBody:
                ReadTopoSingleWireBody(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_TOPO_BrepData:
                id = ReadTopoBrepData(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_TOPO_SingleWireBodyCompress:
                ReadTopoSingleWireBodyCompress(ref r, ctx);
                break;
            case PrcType.PRC_TYPE_TOPO_BrepDataCompress:
                id = ReadTopoBrepDataCompress(ref r, ctx);
                break;
            default:
                ctx.UnknownType(ref r, "PRC_TYPE_TOPO_Body.id", id__type);
                break;
        }
        ctx.Schema.Evaluate(ref r, PrcType.PRC_TYPE_TOPO_Body);
        ctx.Leave();
        return new PrcTopoBody
        {
            Id = id,
            IdType = id__type,
        };
    }

    // PRC_TYPE_TOPO_Context
    internal static PrcTopoContext ReadTopoContext(ref PrcBitReader r, PrcContext ctx)
    {
        ctx.Enter("PRC_TYPE_TOPO_Context", r.BitPosition);
        uint id = r.ReadUnsignedInteger();
        ctx.Expect(id, PrcType.PRC_TYPE_TOPO_Context, "PRC_TYPE_TOPO_Context");
        ReadContentPRCBase(ref r, ctx);
        r.ReadCharacter();
        r.ReadDouble();
        double tolerance = r.ReadDouble();
        bool has_face_thickness = r.ReadBoolean();
        if (has_face_thickness)
        {
            r.ReadDouble();
        }
        bool has_scale = r.ReadBoolean();
        double scale = 0;
        if (has_scale)
        {
            scale = r.ReadDouble();
        }
        uint number_of_bodies = r.ReadUnsignedInteger();
        PrcTopoBody[] bodies = [];
        int bodies__count = ctx.Count(ref r, (long)number_of_bodies, 1);
        ctx.Charge(bodies__count * 40L);
        bodies = new PrcTopoBody[Math.Min(bodies__count, 256)];
        for (int i = 0; i < bodies__count; i++)
        {
            if (i == bodies.Length)
            {
                Array.Resize(ref bodies, (int)Math.Min(bodies.Length * 2L, bodies__count));
            }

            bodies[i] = ReadTopoBody(ref r, ctx);
        }
        ctx.Schema.Evaluate(ref r, PrcType.PRC_TYPE_TOPO_Context);
        ctx.Leave();
        return new PrcTopoContext
        {
            Tolerance = tolerance,
            HasScale = has_scale,
            Scale = scale,
            Bodies = bodies,
        };
    }

    // FileStructureExactGeometry
    internal static PrcFileStructureExactGeometry ReadFileStructureExactGeometry(ref PrcBitReader r, PrcContext ctx)
    {
        ctx.Enter("FileStructureExactGeometry", r.BitPosition);
        uint topo_context_count = r.ReadUnsignedInteger();
        // topo_contexts: https://github.com/pdf-association/pdf-issues/issues/532
        PrcTopoContext[] topo_contexts = [];
        int topo_contexts__count = ctx.Count(ref r, (long)topo_context_count, 18);
        ctx.Charge(topo_contexts__count * 64L);
        topo_contexts = new PrcTopoContext[Math.Min(topo_contexts__count, 256)];
        for (int i = 0; i < topo_contexts__count; i++)
        {
            if (i == topo_contexts.Length)
            {
                Array.Resize(ref topo_contexts, (int)Math.Min(topo_contexts.Length * 2L, topo_contexts__count));
            }

            topo_contexts[i] = ReadTopoContext(ref r, ctx);
        }
        ctx.Leave();
        return new PrcFileStructureExactGeometry
        {
            TopoContexts = topo_contexts,
        };
    }

    // PRC_TYPE_ASM_FileStructureGeometry
    internal static PrcAsmFileStructureGeometry ReadAsmFileStructureGeometry(ref PrcBitReader r, PrcContext ctx)
    {
        ctx.Enter("PRC_TYPE_ASM_FileStructureGeometry", r.BitPosition);
        uint id = r.ReadUnsignedInteger();
        ctx.Expect(id, PrcType.PRC_TYPE_ASM_FileStructureGeometry, "PRC_TYPE_ASM_FileStructureGeometry");
        ReadContentPRCBase(ref r, ctx);
        PrcFileStructureExactGeometry exact_geometry = ReadFileStructureExactGeometry(ref r, ctx);
        ctx.Schema.Evaluate(ref r, PrcType.PRC_TYPE_ASM_FileStructureGeometry);
        ctx.Mark("UserData", r.BitPosition);
        r.SkipUserData();
        ctx.Leave();
        return new PrcAsmFileStructureGeometry
        {
            ExactGeometry = exact_geometry,
        };
    }
}
